/// Registered customer accounts with authentication credentials and profile
/// information. Each customer has a unique email for login, a securely
/// hashed password, and optional profile fields including display name and
/// phone number. Accounts support soft deletion via deleted_at field to
/// preserve historical data.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for customer login and communication.
  email String

  /// Securely hashed password for customer authentication.
  password_hash String

  /// Customer's display name for personalization.
  display_name String?

  /// Customer's phone number for contact purposes.
  phone_number String?

  /// Timestamp when the customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the customer account was soft deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions shopping_mall_customer_sessions[]
  passwordResets shopping_mall_customer_password_resets[]
  emailVerifications shopping_mall_customer_email_verifications[]
  saleReviews shopping_mall_sale_reviews[]
  saleReviewVotes shopping_mall_sale_review_votes[]
  saleQuestions shopping_mall_sale_questions[]
  favorites shopping_mall_sale_favorites[]
  orders shopping_mall_orders[]
  cancellationRequests shopping_mall_cancellation_requests[]
  refundRequests shopping_mall_refund_requests[]
  reviews shopping_mall_reviews[]
  productReviews shopping_mall_product_reviews[]
  userNotifications shopping_mall_user_notifications[]
  notificationPreferences shopping_mall_user_notification_preferences[]
  bannedUser shopping_mall_banned_users?

  @@unique([email])
  @@index([created_at])
}

