/// Registered seller accounts with authentication credentials and profile
/// including approval status.
///
/// This table stores the core information for sellers who register to sell
/// products on the platform. It holds authentication fields (email,
/// password), seller's shop profile (name, description, logo URI), and
/// approval status required for seller activation.
///
/// Related child tables include sessions, password resets, email
/// verifications, approval and suspension records handled separately.
///
/// This table uses soft delete to preserve historical data while allowing
/// logical removal of sellers.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for seller authentication.
  email String

  /// Password hash for secure authentication storage.
  password_hash String

  /// Name of the seller's shop, displayed to customers.
  shop_name String

  /// Optional descriptive text about the seller's shop.
  shop_description String?

  /// Optional URI pointing to the seller's shop logo image.
  logo_uri String? @db.VarChar(80000)

  /// Current approval status of the seller registration. One of: pending,
  /// approved, rejected.
  approval_status String

  /// Reason provided by administrators for rejecting the seller's registration.
  rejection_reason String?

  /// Timestamp when the seller account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion; null means active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions shopping_mall_seller_sessions[]
  emailVerifications shopping_mall_seller_email_verifications[]
  passwordResets shopping_mall_seller_password_resets[]
  profileSnapshots shopping_mall_seller_profile_snapshots[]
  products shopping_mall_products[]
  sales shopping_mall_sales[]
  saleQuestionAnswers shopping_mall_sale_question_answers[]
  refundRequests shopping_mall_refund_requests[]
  shipments shopping_mall_shipments[]
  notificationPreferences shopping_mall_user_notification_preferences[]
  sellerApproval shopping_mall_seller_approvals?
  bannedUser shopping_mall_banned_users?
  sellerSuspensions shopping_mall_seller_suspensions[]

  @@unique([email])
  @@index([approval_status])
  @@index([shop_name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([shop_description(ops: raw("gin_trgm_ops"))], type: Gin)
}

