  const seller2 = await authorize_seller_join(
    { host: connection.host },
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "strong_password_123",
        shopName: "Amazing Deals",
        shopDescription: "Discounts and offers",
        logoUri: null,
      },
