  TestValidator.equals(
    "optionValues matches",
    saleUnit.optionValues,
    optionValuesStr,
  );
  TestValidator.equals(
    "priceOverride is undefined or null",
    saleUnit.priceOverride ?? null,
    null,
  );
  TestValidator.equals(
