    await generate_random_shopping_mall_customer_sales_reviews_create(
      customerConnection,
      {
        params: { saleId: sale.id },
        body: {
          shoppingMallSaleId: sale.id,
          shoppingMallCustomerId: customerJoin.id,
          rating: randint(1, 5),
          body: RandomGenerator.paragraph({ sentences: 3 }),
