    // Check createdAt is within range
    const createdAt = new Date(log.createdAt);
    TestValidator.predicate(
      "createdAt within range",
      createdAt >= new Date(filterBody.createdAtFrom!) &&
        createdAt <= new Date(filterBody.createdAtTo!),
