  const unlikelyUuid = typia.random<string & typia.tags.Format<"uuid">>();
  const body: IShoppingMallAdministrativeAuditLog.IRequest = {
    administratorId: unlikelyUuid,
    limit: 10,
    offset: 0,
  };
