    body: bodyFilter,
    page = 1,
    limit = 10,
  } = props.body;
  const where: Prisma.shopping_mall_review_snapshotsWhereInput = {};
  where.AND = [];
  if (id !== undefined) {
    where.AND.push({ id });
  }
  if (shoppingMallProductReviewId !== undefined) {
    where.AND.push({
