            stockQuantity: productVariant.stock_quantity,
            createdAt: toISOStringSafe(
              productVariant.created_at,
            ) satisfies string & tags.Format<"date-time"> as string &
              tags.Format<"date-time">,
            updatedAt: toISOStringSafe(
