    status,
    createdAtFrom,
    createdAtTo,
    updatedAtFrom,
    updatedAtTo,
    search,
    page = 1,
    limit = 10,
  } = props.body;
  const where: Prisma.shopping_mall_sale_questionsWhereInput = {
    shopping_mall_sale_id: props.saleId,
