          phoneNumber: question.customer.phone_number ?? null,
          createdAt: toISOStringSafe(question.customer.created_at),
          updatedAt: toISOStringSafe(question.customer.updated_at),
        },
      })),
    );
  return {
    pagination: {
      current: pageNumber,
      limit: perPage,
