}): Promise<IPageIShoppingMallOrderSnapshot.ISummary> {
  const { body } = props;
  const where: Prisma.shopping_mall_order_snapshotsWhereInput = {};
  if (body.shoppingMallOrderId) {
    where.shopping_mall_order_id = body.shoppingMallOrderId;
