    where.snapshot_at = {};
    if (body.snapshotAt.start) {
      where.snapshot_at.gte = body.snapshotAt.start;
    }
    if (body.snapshotAt.end) {
      where.snapshot_at.lte = body.snapshotAt.end;
    }
  }
