      email: true,
      display_name: true,
      phone_number: true,
      created_at: true,
      updated_at: true,
    },
  });
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit),
    },
    data: customers.map((customer) => ({
      id: customer.id,
      email: customer.email,
      displayName: customer.display_name ?? null,
      phoneNumber: customer.phone_number ?? null,
