      logoUri: shipment.seller.logo_uri ?? null,
      approvalStatus: shipment.seller.approval_status,
      rejectionReason: shipment.seller.rejection_reason ?? null,
    },
  }));
  return {
    data: shipments,
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
