          grade: record.administrator.administratorGrade.grade,
          superAdministrator:
            record.administrator.administratorGrade.super_administrator,
        },
      },
    })),
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

