export async function patchShoppingMallSellerInventoryHistories(props: {
  seller: SellerPayload;
  body: IShoppingMallInventoryHistory.IRequest;
}): Promise<IPageIShoppingMallInventoryHistory.ISummary> {
  const {
    shoppingMallProductVariantId,
    startDate,
    endDate,
    reason,
    page = 1,
    limit = 100,
  } = props.body;
  const where = {
    deleted_at: null as null,
    ...(shoppingMallProductVariantId
      ? { shopping_mall_product_variant_id: shoppingMallProductVariantId }
      : {}),
    ...(reason ? { reason } : {}),
    ...(startDate || endDate
      ? {
          created_at: {
            ...(startDate ? { gte: startDate } : {}),
            ...(endDate ? { lte: endDate } : {}),
          },
        }
      : {}),
  } satisfies Prisma.shopping_mall_inventory_historiesWhereInput;
  const total = await MyGlobal.prisma.shopping_mall_inventory_histories.count({
    where,
  });
  const skip = (page - 1) * limit;
  const records =
    await MyGlobal.prisma.shopping_mall_inventory_histories.findMany({
      where,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      select: {
        id: true,
        shopping_mall_product_variant_id: true,
        productVariant: {
          select: {
            id: true,
            sku_code: true,
            price_override: true,
            stock_quantity: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
        quantity_delta: true,
        reason: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
  function convertToDateTimeString(date: Date | null): string | null {
    if (date === null) return null;
    return toISOStringSafe(date);
  }
  const data = records.map((record) => ({
    id: record.id,
    shoppingMallProductVariantId: record.shopping_mall_product_variant_id,
    productVariant: {
      id: record.productVariant.id,
      skuCode: record.productVariant.sku_code,
      priceOverride:
        record.productVariant.price_override === null
          ? undefined
          : record.productVariant.price_override,
      stockQuantity: record.productVariant.stock_quantity,
      createdAt: convertToDateTimeString(record.productVariant.created_at),
      updatedAt: convertToDateTimeString(record.productVariant.updated_at),
      deletedAt: convertToDateTimeString(record.productVariant.deleted_at),
    },
    quantityDelta: record.quantity_delta,
    reason: record.reason,
    createdAt: convertToDateTimeString(record.created_at),
    updatedAt: convertToDateTimeString(record.updated_at),
    deletedAt: convertToDateTimeString(record.deleted_at),
  }));
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit),
    },
    data,
  };
}

